        void cow(){var c=EntityTypes.COW.create(level,EntitySpawnReason.COMMAND);require(c!=null,"native source effect witness");c.setPos(origin.add(3,0,7));c.setNoGravity(true);c.setNoAi(true);c.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);c.setHealth(100);require(level.addFreshEntity(c),"actual living native effect witness");witness=c;}
